{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "An eligible school is a public senior high school, including a public charter school.",
      "rationale": "Conveys the public senior high school limitation and inclusion of public charter schools. The statutory definition cross-reference is not essential here."
    },
    {
      "proposition_id": "P2",
      "status": "partial",
      "summary_quote": "The bill defines these products to include tampons, panty liners, menstrual cups, sanitary napkins, and similar products or materials.",
      "rationale": "Includes the listed examples but omits the broader definition covering products designed for menstruation or other genital-tract secretions."
    },
    {
      "proposition_id": "P3",
      "status": "partial",
      "summary_quote": "Each local education agency and public charter school would have to provide menstrual hygiene products at no charge in every women’s and girls’ bathroom and locker room, and through the school nurse, in each eligible school building where instruction is provided. An eligible school is a public senior high school, including a public charter school. Products are for student use only, and the requirement excludes bathrooms and locker rooms designated specifically for teachers or staff.",
      "rationale": "Conveys the responsible entities, free provision, instructional-building scope, nurse access, and staff-only exception. However, its wording limits locker rooms to women’s and girls’ locker rooms rather than conveying the bill’s requirement for all locker rooms other than those designated for teachers or staff."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "Products are for student use only",
      "rationale": "Expressly conveys the student-only use restriction."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "The Department of Education could develop policies and offer guidance to help schools comply.",
      "rationale": "Conveys the department’s discretionary authority to develop policies and provide compliance guidance, using schools as shorthand for the covered school entities and their governing bodies."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "effective July 1, 2025",
      "rationale": "States the exact effective date."
    }
  ]
}
